/** 世界书生图的格式:nai = Scene Composition / Character N Prompt;anima = size / Scene / CharN / Description。 */
export type WorldbookFormat = 'nai' | 'anima';
export const WORLDBOOK_FORMATS: { value: WorldbookFormat; label: string }[] = [
  { value: 'nai', label: 'NAI' },
  { value: 'anima', label: 'Anima' },
];

/**
 * 破限词来源。
 * - custom: 用 `AutoTagPrompts.jailbreak` 的自定义文本(留空回落内置默认),存量行为。
 * - stPreset: 实时读取酒馆当前聊天补全预设,按勾选的 identifier 拼接。
 */
export interface JailbreakSource {
  mode: 'custom' | 'stPreset';
  /** stPreset 模式下勾选的提示词 identifier;拼接顺序跟预设顺序,不按此数组顺序。 */
  presetEntries: string[];
}

/** 新装/切到跟随预设时的默认勾选:越狱 + NSFW 两条,最贴近「破限词」的用途。 */
export const DEFAULT_JAILBREAK_PRESET_ENTRIES = ['jailbreak', 'nsfw'];

export interface AutoTagSettings {
  /** 新 AI 正文落地后自动请求模型。 */
  enabled: boolean;
  /** 发送最近多少个 AI 故事楼及其间 user 楼的清洗后正文；目标楼计入数量。 */
  contextMessages: number;
  /** 单楼要求模型返回的最少画面数；0 = 允许没有值得绘制的画面。 */
  minImages: number;
  /** 单楼允许模型选择的最大画面数。 */
  maxImages: number;
  /** 生成失败自动重试次数(请求异常或返回无法解析都算),0 = 不重试,默认 1。 */
  retryCount: number;
  /** 写入 tag 后是否立即调用出图渠道自动生成图片(默认开;关闭则卡片上手动点「生成」)。 */
  autoGenerate: boolean;
  /**
   * 生成 tag 期间在酒馆里弹一条常驻进度提示(默认开,见 autoTag/notice.ts)。
   *
   * 存这里而不是 settings.ui:它只影响自动 tag 这条链路,查「为什么没提示」的人
   * 会先翻自动 tag 设置。存储位置跟功能走,不跟控件类型走。
   */
  notifyProgress: boolean;
  /**
   * 世界书生图(默认关):主 API 按世界书要求已在正文里写好 `image###…###` 生图词时,
   * 直接转成 <bbi_image> 卡片并出图,不再请求副 API(见 autoTag/worldbookImage.ts)。
   * 开着时没有生图词的楼不自动生成 tag——省请求正是这个开关的目的;手动按钮照常可用。
   */
  worldbookImages: boolean;
  /**
   * 世界书生图按哪种格式读生图词(见 WORLDBOOK_FORMATS)。**只管怎么读**,出图仍走当前出图渠道。
   * 由用户选而不从内容猜:两种格式的键名有重叠(Scene / Scene Composition),猜错会静默读歪。
   */
  worldbookFormat: WorldbookFormat;
  /** 可编辑提示词集(破限/后端规范/思维链);空串 = 回落内置默认。 */
  prompts: AutoTagPrompts;
  /**
   * 破限词来源(后加字段,可选以兼容旧配置)。
   * 缺省 = custom:只用 `prompts.jailbreak`,行为与加功能前完全一致。
   * 选 stPreset 时才读取酒馆当前聊天补全预设;读不到自动回退 custom/内置默认。
   */
  jailbreakSource?: JailbreakSource;
}

/** 世界书链条目的**消息角色**(发给 AI 的 system/user/assistant),与角色卡里的角色无关。 */
export type WorldbookChainMessageRole = 'system' | 'user' | 'assistant';
/** always = 无条件发送;trigger = 命中 triggerWords(且 andTriggerWords)才发送。 */
export type WorldbookChainTriggerMode = 'always' | 'trigger';

/** 世界书链条目:只保留组装请求需要的字段,导入时的 UUID/激活色等元数据不落盘。 */
export interface WorldbookChainEntry {
  id: string;
  name: string;
  /** 该条消息以什么身份发给 AI(system/user/assistant),保留世界书原值。 */
  role: WorldbookChainMessageRole;
  content: string;
  enabled: boolean;
  triggerMode: WorldbookChainTriggerMode;
  /** 逗号/顿号分隔,任一词命中即通过。 */
  triggerWords: string;
  /** 逗号/顿号分隔,整组都命中才通过;空串 = 不启用第二组。 */
  andTriggerWords: string;
}

export interface WorldbookChainBook {
  id: string;
  name: string;
  importedAt: number;
  entries: WorldbookChainEntry[];
}

/**
 * 世界书链(独立大类):用导入的世界书替代内置思维链与破限词,请求仍走自动 tag 的渠道链。
 * 开关打开时覆盖「自动生成 tag」与「世界书生图」;单槽重写仍走旧链(整楼链没有槽位概念)。
 */
export interface WorldbookChainSettings {
  enabled: boolean;
  activeBookId: string;
  /** 单楼最多取几张;世界书自己要求 4–10,这里只做硬上限。 */
  maxImages: number;
  /** 是否在提示词里要求每个 image### 正文不超过 tagLimitChars 字符。 */
  enforceTagLimit: boolean;
  /** 单张 image### 正文的字符上限(上游生图模型按约 2000 token 接收)。 */
  tagLimitChars: number;
  books: WorldbookChainBook[];
}

/** 世界书链硬上限;settings 会随每次改动整体落盘,书太多会把保存拖慢。 */
export const WORLDBOOK_CHAIN_MAX_BOOKS = 5;
export const WORLDBOOK_CHAIN_MAX_IMAGES = 20;
export const WORLDBOOK_CHAIN_DEFAULT_MAX_IMAGES = 10;
export const WORLDBOOK_CHAIN_TAG_LIMIT_MIN = 1;
export const WORLDBOOK_CHAIN_TAG_LIMIT_MAX = 2000;
